function assert(condition,message){if(!condition)throw new Error(message)}
function safeReset(target){
  const resolved=resolve(target)
  assert(resolved.startsWith(`${verifyRoot}${sep}`),`Unsafe verification target: ${resolved}`)
  if(existsSync(resolved))rmSync(resolved,{recursive:true,force:true})
  mkdirSync(resolved,{recursive:true})
}
function run(command,args,{cwd=root,env={}}={}){
  const result=spawnSync(command,args,{cwd,env:{...process.env,...env},encoding:'utf8',windowsHide:true,maxBuffer:16*1024*1024})
  if(result.status!==0)throw new Error(`${command} ${args.join(' ')} failed (${result.status})${result.error?` ${result.error.stack||result.error.message}`:''}\n${result.stdout||''}\n${result.stderr||''}`)
  return `${result.stdout||''}${result.stderr||''}`.trim()
}
function runPnpm(args,options={}){
  const pnpm=process.env.npm_execpath
  if(pnpm&&/pnpm/i.test(pnpm)&&existsSync(pnpm))return run(process.execPath,[pnpm,...args],options)
  const bundledPnpm=resolve(dirname(process.execPath),'..','node_modules','pnpm','bin','pnpm.mjs')
  if(existsSync(bundledPnpm))return run(process.execPath,[bundledPnpm,...args],options)
  return run(process.platform==='win32'?'pnpm.cmd':'pnpm',args,options)
}
function parsePackJson(output){
  const start=output.indexOf('{')
  const end=output.lastIndexOf('}')
  assert(start>=0&&end>start,`pnpm pack did not return JSON: ${output}`)
  const parsed=JSON.parse(output.slice(start,end+1))
  return Array.isArray(parsed)?parsed[0]:parsed
}
function collectFiles(folder){
  const result=[]
  for(const entry of readdirSync(folder,{withFileTypes:true})){
    const path=join(folder,entry.name)
    if(entry.isDirectory())result.push(...collectFiles(path))
    else result.push(path)
  }
  return result
}
function sha256(path){return createHash('sha256').update(readFileSync(path)).digest('hex')}

